<?php
require __DIR__.'/../../backend/vendor/autoload.php';
$source=file_get_contents(__DIR__.'/../../backend/routes/api_v1.php');
$mobileAt=strpos($source,"Route::prefix('mobile')");
$rootSessionAt=strpos($source,"Route::middleware('api.session')");
$mobileSessionAt=strpos($source,"Route::middleware('api.session')",$mobileAt);
$routes=[];
$add=function(string $method,string $path,int $offset) use (&$routes,$mobileAt,$rootSessionAt,$mobileSessionAt,$source):void {
    $mobile=$offset>$mobileAt;
    if($mobile) $path='/mobile'.$path;
    $next=strpos($source,'Route::',$offset+7);$end=$next===false?strlen($source):$next;
    $chunk=substr($source,$offset,$end-$offset);
    preg_match_all('/api\.permission:([A-Za-z0-9_.,-]+)/',$chunk,$matches);
    $permissions=array_values(array_unique($matches[1]));
    $csrf=str_contains($chunk,'api.csrf')?'required':'-';
    $stepUp=str_contains($chunk,'api.step_up')?'required':'-';
    if(!$mobile){
        $auth=$offset>$rootSessionAt?'session (api.session)':(str_contains($path,'/health')||str_ends_with($path,'/auth/login')?'public':'sessionless customer-picker');
    }else{
        $auth=$offset>$mobileSessionAt?'session (api.session)':(str_ends_with($path,'/auth/login')?'public':'mobile bearer (api.mobile)');
    }
    $routes[]=['method'=>strtoupper($method),'path'=>$path,'auth'=>$auth,'csrf'=>$csrf,'step_up'=>$stepUp,'permissions'=>$permissions?:['none declared on route; inspect controller/group']];
};
preg_match_all('/Route::(get|post|put|patch|delete|options|any)\s*\(\s*[\'\"]([^\'\"]+)[\'\"]/i',$source,$simple,PREG_OFFSET_CAPTURE);
foreach($simple[0] as $i=>$m)$add($simple[1][$i][0],$simple[2][$i][0],$m[1]);
preg_match_all('/Route::match\s*\(\s*\[([^\]]+)\]\s*,\s*[\'\"]([^\'\"]+)[\'\"]/i',$source,$matches,PREG_OFFSET_CAPTURE);
foreach($matches[0] as $i=>$m){preg_match_all('/[\'\"](get|post|put|patch|delete|options|head)[\'\"]/i',$matches[1][$i][0],$methods);foreach($methods[1] as $method)$add($method,$matches[2][$i][0],$m[1]);}
$doc=Symfony\Component\Yaml\Yaml::parseFile(__DIR__.'/../../backend/docs/openapi.yaml');
$routesByOperation=[];foreach($routes as $route)$routesByOperation[$route['method'].' '.$route['path']]=true;
$openapi=[];foreach($doc['paths'] as $path=>$ops)foreach($ops as $method=>$unused)$openapi[strtoupper($method).' '.$path]=true;
$missing=array_values(array_diff(array_keys($routesByOperation),array_keys($openapi)));
$orphan=array_values(array_diff(array_keys($openapi),array_keys($routesByOperation)));
$report="# Route permission audit and OpenAPI operation comparison\n\nGenerated by parsing backend/routes/api_v1.php without booting Laravel or reading .env, and Symfony-parsing backend/docs/openapi.yaml. Route method and full path, including parameter names, are compared exactly.\n\n- Route operations: **".count($routesByOperation)."**\n- OpenAPI operations: **".count($openapi)."**\n- Matched: **".(count($routesByOperation)-count($missing))."**\n- Missing OpenAPI: **".count($missing)."**\n- OpenAPI without route: **".count($orphan)."**\n\n## Permission and authentication inventory\n\napi.permission entries are route-level permissions. CSRF and step-up columns show direct middleware; authentication reflects the enclosing session/mobile group. Rows without a route permission need controller-level review.\n\n| Method | Path | Authentication | CSRF | Step-up | Route permissions |\n|---|---|---|---|---|---|\n";
usort($routes,fn($a,$b)=>[$a['path'],$a['method']]<=>[$b['path'],$b['method']]);
foreach($routes as $route)$report.='| '.$route['method'].' | `'.$route['path'].'` | '.$route['auth'].' | '.$route['csrf'].' | '.$route['step_up'].' | '.implode(', ',$route['permissions'])." |\n";
$report.="\n## Operations missing from OpenAPI\n\n".($missing?implode("\n",array_map(fn($v)=>'- '.$v,$missing)):'None')."\n\n## OpenAPI operations without routes\n\n".($orphan?implode("\n",array_map(fn($v)=>'- '.$v,$orphan)):'None')."\n";
file_put_contents(__DIR__.'/ROUTE_PERMISSION_AUDIT.md',$report);
echo 'Route operations='.count($routesByOperation).' OpenAPI operations='.count($openapi).' matched='.(count($routesByOperation)-count($missing)).' missing='.count($missing).' orphan='.count($orphan).PHP_EOL;